import { Component, OnInit } from "@angular/core";
import { ProjectService } from "src/app/services/project.service";

@Component({
  selector: "app-admin-projects",
  templateUrl: "./admin-projects.component.html",
  styleUrls: ["./admin-projects.component.css"],
})
export class AdminProjectsComponent implements OnInit {
  projects: any[] = [];

  project = {
    title: "",
    description: "",
    image: "",
  };

  loading = true;
  errorMessage = "";
  successMessage = "";

  constructor(private projectService: ProjectService) {}

  ngOnInit(): void {
    this.loadProjects();
  }

  loadProjects(): void {
    this.projectService.getProjects().subscribe({
      next: (data) => {
        this.projects = data;
        this.loading = false;
      },
      error: (error) => {
        console.error(error);
        this.errorMessage = "Unable to load projects.";
        this.loading = false;
      },
    });
  }

  addProject(): void {
    this.successMessage = "";
    this.errorMessage = "";

    if (!this.project.title || !this.project.description) {
      this.errorMessage = "Title and description are required.";
      return;
    }

    this.projectService.createProject(this.project).subscribe({
      next: () => {
        this.successMessage = "Project added successfully.";

        this.project = {
          title: "",
          description: "",
          image: "",
        };

        this.loadProjects();
      },

      error: (error) => {
        console.error(error);
        this.errorMessage = "Unable to add project.";
      },
    });
  }

  deleteProject(id: number): void {
    if (!confirm("Are you sure you want to delete this project?")) {
      return;
    }

    this.projectService.deleteProject(id).subscribe({
      next: () => {
        this.loadProjects();
      },
      error: (error) => {
        console.error(error);
        this.errorMessage = "Unable to delete project.";
      },
    });
  }

  editing = false;
  editingId: number | null = null;

  editProject(project: any): void {
    this.editing = true;
    this.editingId = project.id;

    this.project = {
      title: project.title,
      description: project.description,
      image: project.image,
    };
  }

  updateProject(): void {
    if (this.editingId === null) {
      return;
    }

    this.projectService.updateProject(this.editingId, this.project).subscribe({
      next: () => {
        alert("Project updated successfully");

        this.editing = false;
        this.editingId = null;

        this.project = {
          title: "",
          description: "",
          image: "",
        };

        this.loadProjects();
      },

      error: (error) => {
        console.error(error);
        alert("Failed to update project");
      },
    });
  }

  cancelEdit(): void {
    this.editing = false;
    this.editingId = null;

    this.project = {
      title: "",
      description: "",
      image: "",
    };
  }
}
